WITH valid AS (SELECT id, device_code, reading_ts, pressure, status_bits, firmware, UPPER(device_code) AS device_code_upper, CONCAT_WS(',', device_code, firmware) AS device_code_firmware_key FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 01:00:00' AND humidity <= 70), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM valid), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, DATE_TRUNC('HOUR', reading_ts) AS hour_window, COUNT(*) FILTER (WHERE device_code = 'DV-01') AS dv_01_rows, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, CORR(pressure, status_bits) AS corr_pressure_status_bits, RANK() OVER (PARTITION BY DATE_TRUNC('DAY', reading_ts) ORDER BY CORR(pressure, status_bits) DESC) AS corr_pressure_status_bits_rank FROM islands GROUP BY activity_day, hour_window HAVING CORR(pressure, status_bits) > 0 ORDER BY corr_pressure_status_bits DESC NULLS LAST;
